def has_close_elements(numbers: List[float], threshold: float) -> bool:
    if not numbers or len(numbers) < 1:
        return False
    for i in range(len(numbers)-1):
        if abs(numbers[i] - numbers[i+1]) < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    stack = []

    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            stack.pop()
            if not stack:
                groups.append(''.join(stack))
                stack = []
        else:
            continue

    return groups

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        raise ValueError("Cannot calculate MAD for an empty list")
    x_mean = mean(numbers)
    mad = 0.0
    for x in numbers:
        mad += abs(x - x_mean)
    mad /= len(numbers)
    return mad

def find_number_combinations():
    combinations = list()
    for i in range(1, 4):
        for j in range(2, 7):
            for k in range(3, 10):
                if i*j is k*j:
                    combinations.append((i, j, k))
    return combinations

def sum_of_factorials_optimized(n: int) -> int:
    if n < 1 or n > 50:
        raise ValueError(f"Invalid value of n: {n}. The value of n should be in the range of 1 to 50, inclusive.")
    factorial_sum = 0
    for i in range(1, n + 1):
        factorial_sum += i * factorial_sum
    return factorial_sum

def cantor_numbering(N):
