        return "0/1"
    elif N == 1:
        return "1/1"
    else:
        c = (N*(N+1))//2
        d = N*N
        return str(c) + "/" + str(d)

def max_product(num_str, N, K):
    # Initialize variables
    products = [1] * (N - 1)
    multipliers = [0] * (N - 1)

    # Iterate through the number string and calculate products
    for i in range(1, N):
        products[i - 1] = products[i - 2] * int(num_str[i - 1])

    # Calculate the maximum product
    for i in range(K):
        multipliers[i] = products[N - 2 - i] // int(num_str[N - 2 - i])

    # Return the maximum product
    return max(multipliers)

