def count_passing_ways(n: int, m: int) -> int:
    if n < 1 or m < 1:
        return 0
    if m == 1 or n == 1:
        return 1
    if m == 2 and n == 2:
        return 2

    # Dynamic programming approach
    # Initialize the dp table with 1s for base cases and 0s otherwise
    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 2

    # Fill in the dp table using the recurrence relation
    for i in range(3, n + 1):
        for j in range(1, m + 1):
            dp[i] += dp[i - 1] + dp[i - 2]

    return dp[n]

def max_energy(beads):
    # Initialize the maximum energy to 0
    max_energy = 0

    # Use dynamic programming to find the maximum energy release
    for i in range(1, len(beads)):
        for j in range(0, i):
            # Calculate the energy release by merging the beads in the ith and jth positions
            energy = beads[i] * beads[j] * beads[j + 1]

            # Update the maximum energy if the current release is greater than the previous maximum
            if energy > max_energy:
                max_energy = energy

    # Return the maximum energy
    return max_energy

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n+1):
        coeff = coeffs[i]
        degree = n - i
        if coeff != 0:
            term = ""
            if coeff < 0:
                term += "-"
            elif i != 0:
                term += "+"
            if abs(coeff) != 1 or degree == 0:
                term += str(abs(coeff))
            term += "x"
            if degree > 1:
                term += "^" + str(degree)
            terms.append(term)
    return "".join(terms)

def select_volunteers(n, m, applicants):
    if len(applicants) <= m:
        return (min(applicants, key=lambda x: x[1]), applicants)

    sorted_applicants = sorted(applicants, key=lambda x: x[1], reverse=True)
    cutoff = int((m * 1.5) // 1)
    qualified_applicants = [applicant for applicant in sorted_applicants if applicant[1] >= cutoff]
    return (cutoff, qualified_applicants)

def decode(encoded: str, original: str, message: str) -> str:
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(encoded)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        elif mapping[encoded[i]] != original[i]:
            return "Failed"

    # Construct the decoded message
    decoded_message = ""
    for char in message:
        if char not in mapping:
            return "Failed"
        decoded_message += mapping[char]

    return decoded_message

def largest_prime_factor(n: int) -> int:
    prime_factors = []
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            prime_factors.append(i)
            n = n // i
    if prime_factors:
        return prime_factors[-1]
    else:
        return n

def count_partitions(n, k, x):
    if n == 0 or k == 0:
        return 1
    if x > n:
        return 0
    if k == 1:
        return 1
    return count_partitions(n-x, k-1, x) + count_partitions(n, k, x+1)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n == 1:
        return 1
    if n not in memo:
        memo[n] = sum(count_sequences(n-1, last-i, memo) for i in range(1, int(last/2)+1))
    return memo[n]

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        if gcd(a, y0 // x0) == 1:
            b = y0 // (a * x0)
            if a == b:
                count += 1
            else:
                count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    inorder_indices = {c: i for i, c in enumerate(inorder)}
    root = postorder[-1]
    inorder_root = inorder_indices[root]
    left_subtree = inorder[:inorder_root]
    right_subtree = inorder[inorder_root+1:]
    left_subtree_postorder = postorder[:len(left_subtree)]
    right_subtree_postorder = postorder[len(left_subtree):-1]
    return preorder_traversal(left_subtree, left_subtree_postorder) + preorder_traversal(right_subtree, right_subtree_postorder)

def string_transformation(A: str, B: str, rules: List[Tuple[str, str]]) -> Union[int, str]:
    step_count = 0
    current = A
    queue = [current]

    while queue:
        step_count += 1
        if step_count > 10:
            return "NO ANSWER!"

        current = queue.pop(0)
        for rule in rules:
            if rule[0] in current:
                current = current.replace(rule[0], rule[1])
                queue.append(current)
                break

        if current == B:
            return step_count

    return "NO ANSWER!"

def find_min_n_greater_than_k(k: int) -> int:
    n = 0
    while True:
        n += 1
        s = sum(1 / x for x in range(1, n + 1))
        if s > k:
            return n

def generate_numbers(n, rules):
    num_unique = 1
    seen = set([n])
    queue = deque([n])
    while queue:
        num = queue.popleft()
        for rule in rules:
            new_num = num
            while True:
                if new_num == 0:
                    break
                digit = new_num % 10
                new_num //= 10
                if digit == rule[0]:
                    new_num = new_num * 10 + rule[1]
                    if new_num not in seen:
                        seen.add(new_num)
                        queue.append(new_num)
                        num_unique += 1
                        break
    return num_unique

def calculate_score(system: int, points: str) -> list:
    scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        else:
            opponent_score += 1

        if player_score == opponent_score + 2 and player_score >= system:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 and player_score < system:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    """
    Calculate the nth Catalan number using dynamic programming.

    Args:
        n (int): The position in the Catalan number sequence to compute (must be non-negative).

    Returns:
        int: The nth Catalan number.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer.")
    if n == 0:
        return 1
    return sum(catalan_number(i) * catalan_number(n-i-1) for i in range(n))

