def max_herb_value(T, M, herbs):
    max_value = 0
    for i in range(len(herbs)):
        t, v = herbs[i]
        if t <= T:
            max_value = max(max_value, v)
            T -= t
    return max_value

def calculate_arrangements(n, m, a):
    # base case: if there are no pots to arrange, return 1
    if m == 0:
        return 1

    # initialize the number of arrangements to 0
    arrangements = 0

    # loop through each type of flower
    for i in range(n):
        # if the current type of flower has at least as many pots as the number of pots left to arrange
        if a[i] >= m:
            # add the number of arrangements for the current type of flower to the total
            arrangements += calculate_arrangements(n, m - a[i], a)

    # return the total number of arrangements
    return arrangements % (10**6 + 7)

def mod_inverse(a, b):
    if gcd(a, b) != 1:
        return None
    else:
        x, y, g = xgcd(a, b)
        return x % b

def find_most_unhappy_day(schedule: list[tuple[int, int]]) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0
    for day in schedule:
        total_hours = day[0] + day[1]
        if total_hours > max_unhappiness:
            max_unhappiness = total_hours
            most_unhappy_day = day[1]
    return most_unhappy_day

def next_permutation(perm: list) -> bool:
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i+1]:
            for j in range(i+1, len(perm)):
                if perm[j] > perm[i]:
                    perm[i], perm[j] = perm[j], perm[i]
                    return True
    return False

def jinjin_savings_plan(budgets: List[int]) -> int:
    total_amount = 0
    for i, budget in enumerate(budgets, start=1):
        if budget >= 100:
            savings = round(budget / 100) * 100
            total_amount += savings
            total_amount *= 1.2
        else:
            return -i
    return int(total_amount)

def minimum_students_to_leave(heights):
    if len(heights) < 3:
        return 0

    heights.sort()
    left = [heights[0]]
    right = [heights[-1]]
    min_moves = 0

    for i in range(1, len(heights) - 1):
        if heights[i] < left[-1]:
            left.append(heights[i])
        elif heights[i] < right[-1]:
            right.append(heights[i])
        elif heights[i] > left[-1]:
            min_moves += 1
            left.append(heights[i])
        else:
            min_moves += 1
            right.append(heights[i])

    return min_moves

def hanoi_double_iterative(n: int) -> int:
    total_moves = 0
    for i in range(1, n+1):
        moves = 2**i * (2**i - 1)
        total_moves += moves
    return total_moves
